package main

import (
	"bytes"
	"embed"
	"fmt"
	"os"
	"path/filepath"
)

const appVersion = "1.4.0"

// payload is generated by build/build-exe.ps1 from the tracked PowerShell source.
//go:embed payload/Manager.ps1 payload/Engine/Scanner.ps1 payload/Engine/Downloader.ps1 payload/Engine/Supervisor.ps1
var payload embed.FS

func writeIfChanged(path string, data []byte) error {
	if old, err := os.ReadFile(path); err == nil && bytes.Equal(old, data) {
		return nil
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, data, 0o644); err != nil {
		return err
	}
	if err := os.Rename(tmp, path); err != nil {
		_ = os.Remove(path)
		if err2 := os.Rename(tmp, path); err2 != nil {
			_ = os.Remove(tmp)
			return err2
		}
	}
	return nil
}

func appRoot() (string, error) {
	base := os.Getenv("LOCALAPPDATA")
	if base == "" {
		var err error
		base, err = os.UserCacheDir()
		if err != nil {
			return "", err
		}
	}
	return filepath.Join(base, "ChatAttachmentManager", "App", appVersion), nil
}

func materializePayload(root string) (string, error) {
	files := map[string]string{
		"payload/Manager.ps1":             "Manager.ps1",
		"payload/Engine/Scanner.ps1":      filepath.Join("Engine", "Scanner.ps1"),
		"payload/Engine/Downloader.ps1":   filepath.Join("Engine", "Downloader.ps1"),
		"payload/Engine/Supervisor.ps1":   filepath.Join("Engine", "Supervisor.ps1"),
	}
	for embedded, relative := range files {
		data, err := payload.ReadFile(embedded)
		if err != nil {
			return "", fmt.Errorf("read embedded %s: %w", embedded, err)
		}
		if err := writeIfChanged(filepath.Join(root, relative), data); err != nil {
			return "", fmt.Errorf("write %s: %w", relative, err)
		}
	}
	return filepath.Join(root, "Manager.ps1"), nil
}

func main() {
	root, err := appRoot()
	if err != nil {
		showError("Chat Attachment Manager", "Cannot resolve LocalAppData: "+err.Error())
		return
	}
	manager, err := materializePayload(root)
	if err != nil {
		showError("Chat Attachment Manager", "Cannot prepare embedded engine: "+err.Error())
		return
	}
	if err := launchPowerShellManager(manager); err != nil {
		showError("Chat Attachment Manager", "Cannot start Windows PowerShell: "+err.Error())
	}
}
